pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 potBefore, bool shouldWin) public {
        // Restrict potBefore to a feasible range to avoid overflow on balance/transfers
        potBefore = bound(potBefore, 1, 1000 ether);
        // Ensure potBefore is at least TICKET_AMOUNT to allow a full win payout
        vm.assume(potBefore >= 10);
        // Force a win or loss by controlling the randomness outcome
        // We set up the contract with a pre-existing pot
        vm.store(address(c), bytes32(uint256(2)), bytes32(potBefore));
        // We need to call play() with the exact TICKET_AMOUNT
        vm.deal(address(this), 10 ether);
        // Override timestamp and difficulty to ensure the random result matches shouldWin
        // keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender)) % 2 == 0 when shouldWin
        if (shouldWin) {
            vm.warp(0);
            vm.difficulty(0);
        } else {
            vm.warp(1);
            vm.difficulty(0);
        }
        c.play{value: 10}();
        // After a winning play, pot must be 0 in the reference; mutant will have potBefore
        if (shouldWin) {
            assertTrue(c.pot() == 0);
        } else {
            // No assertion needed for loss case; just ensure no revert
            assertTrue(true);
        }
    }
}

