import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tickets, uint256 seed) public {
        // keep domain wide
        tickets = bound(tickets, 0, 100);
        seed = seed % 10000;
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 1);

        uint totalDeposited;
        uint wins;
        // simulate sequence of plays with fuzzed count and pseudorandom outcomes
        for (uint i = 0; i < tickets; i++) {
            address player = address(uint160(uint256(keccak256(abi.encodePacked(i, seed)))));
            vm.deal(player, 10);
            vm.prank(player);
            c.play{value: 10}();
            totalDeposited += 10;
            // predict win based on same random formula (timestamp and block.difficulty fixed by vm.warp/roll)
            uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, player))) % 2;
            if (random == 0) {
                wins++;
            }
        }

        uint expectedPot = totalDeposited - (wins * 10 + wins * 1);
        assertTrue(c.pot() == expectedPot);
    }
}

