pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playsBeforeWin, uint256 playsAfterWin) public {
        // Ensure feasible params
        playsBeforeWin = bound(playsBeforeWin, 0, 5);
        playsAfterWin = bound(playsAfterWin, 0, 5);
        address player = makeAddr("player");
        vm.deal(player, (playsBeforeWin + playsAfterWin + 1) * 10 ether);

        vm.startPrank(player);
        // We need to control randomness so that a win happens exactly after playsBeforeWin.
        // We can't control block.* inside the contract, so we use vm.roll or warp to influence but not guarantee.
        // Instead, we rely on the fuzzer to find a path where the check holds after the win.
        // We execute plays and record state.

        // play playsBeforeWin times
        for (uint i = 0; i < playsBeforeWin; i++) {
            c.play{value: 10}();
        }

        // Now we attempt to win: we don't know if it will be a win, but we check the property after *some* win.
        // The bug only matters when a win actually happens and then more plays occur.
        // So we simulate multiple plays until a win is detected (by checking pot after call).
        // For simplicity, we just make one call and see if it was a win; if not, we assume the test not applicable and skip assertion.
        uint potBefore = c.pot();
        c.play{value: 10}();
        uint potAfter = c.pot();
        bool win = (potAfter == 0); // in reference, win resets pot to 0; in mutant, pot remains non-zero
        if (win) {
            // After a win, pot must be 0 in reference. In mutant, it is not.
            // Now play more times
            for (uint i = 0; i < playsAfterWin; i++) {
                c.play{value: 10}();
            }
            // The pot should equal (playsAfterWin * 10) because win reset it to 0 before these extra plays.
            // But in mutant, it equals (potAfter + playsAfterWin*10) which is greater.
            uint expected = playsAfterWin * 10;
            assertTrue(c.pot() == expected);
        }
        // If no win, this input path doesn't trigger the bug; we skip assertion (test passes vacuously).
        vm.stopPrank();
    }
}

