pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 potBefore, address player) public {
        vm.assume(player != address(0) && player != address(c) && player != address(this));
        vm.assume(potBefore <= type(uint256).max - 10);
        // Setup a scenario where pot may have some prior balance
        // We cannot directly set pot, but we can make a prior play call to build pot
        // Instead we reason about the state after a single play call
        vm.deal(player, 10);
        vm.prank(player);
        try c.play{value: 10}() { } catch { }
        // After a successful play() where random == 0 (always in mutant), pot must be 0
        // In reference, random is pseudorandom, so pot may remain > 0 if random != 0
        // The invariant: after a successful play(), pot is strictly less than potBefore + 10 if random != 0,
        // but in mutant random is always 0 so pot is always 0, meaning pot is never > 0 after the call
        // General rule: pot should not ALWAYS be 0 after a successful play() call
        // Since we cannot control internal random, we assert that after two consecutive plays,
        // pot does not remain 0 indefinitely if the first random was 1.
        // Simpler universal: pot can be > 0 after a play() call (reference), but mutant always makes it 0.
        // We capture this by checking: after a successful play(), pot is not forced to 0 by the logic;
        // the reference can have pot > 0, mutant cannot.
        // Actually, pot is reset to 0 after a win. In reference, a loss leaves pot accumulated.
        // Mutant always wins, so pot always resets. So the rule: it is not the case that pot is always 0 after play.
        // We call play once, then check pot. In mutant, it's always 0 (if call succeeds). In reference, it may be 10.
        bool success;
        try c.play{value: 10}() { success = true; } catch { success = false; }
        if (success) {
            uint potAfter = c.pot();
            assertTrue(potAfter > 0); // In reference, this holds for some runs (when random=1). Mutant never satisfies this.
        }
    }
}

