pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint8 n) public {
        vm.assume(caller != address(0) && caller != address(c) && n > 0 && n <= 5);
        // Record initial balances
        uint initialCallerBalance = caller.balance;
        uint initialBankBalance = c.bank().balance;
        // Give caller enough Ether for n tickets
        uint ticketCost = 10;
        uint totalCost = ticketCost * n;
        vm.deal(caller, totalCost);
        // Call play() n times via the caller
        vm.startPrank(caller);
        for (uint i = 0; i < n; i++) {
            c.play{value: ticketCost}();
        }
        vm.stopPrank();
        // After n calls, compute balance changes
        uint finalCallerBalance = caller.balance;
        uint finalBankBalance = c.bank().balance;
        int callerDelta = int(finalCallerBalance) - int(initialCallerBalance);
        int bankDelta = int(finalBankBalance) - int(initialBankBalance);
        // In the correct contract, the sum of deltas is NOT always -n * 1 (the fixed per-game fee),
        // because sometimes random!=0 and the pot grows without payout, changing balance distribution.
        // In the mutant, random is always 0, so every game pays the bank 1 and resets pot, making sum always -n * 1.
        // The reference contract satisfies: callerDelta + bankDelta != -1 * int(n) for at least some sequences
        // (because accumulated pot stays in contract, not paid out).
        // The mutant always makes this equality hold, so the assertion detects the difference.
        assertTrue(callerDelta + bankDelta != -1 * int(n));
    }
}

