pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 numPlays, uint16 seed) public {
        // Restrict to a reasonable number of plays to avoid out-of-gas and keep replay costs manageable.
        numPlays = bound(numPlays, 1, 100);

        uint256 totalSent = 0;
        // Record the initial ETH balance of C that is NOT due to players.
        // In the reference, only player pay-ins modify C balance and pot.
        uint256 initialNonPlayerBalance = address(c).balance;

        // Simulate a sequence of plays.
        vm.startPrank(address(this));
        // Use seed to generate deterministic pseudo-random values via keccak256.
        for (uint256 i = 0; i < numPlays; i++) {
            // Fresh seed for each iteration, staying within fuzz inputs.
            bytes32 hash = keccak256(abi.encode(seed, i));
            // Ensure the contract always receives exactly TICKET_AMOUNT per play.
            uint256 value = 10; // TICKET_AMOUNT = 10
            vm.deal(address(this), value);
            (bool ok,) = address(c).call{value: value}(abi.encodeWithSignature("play()"));
            // The play may fail in the mutant if it runs out of funds; we ignore reverts
            // because the property is about state after successful plays.
            if (ok) {
                totalSent += value;
            }
        }
        vm.stopPrank();

        // General rule: pot == (total player contributions) - (ETH that has left the contract due to wins).
        // The ETH that has left the contract = totalSent - (address(c).balance - initialNonPlayerBalance).
        // Thus pot == address(c).balance - initialNonPlayerBalance.
        // This holds for reference C but fails for mutant when a win sends the full pot to bank,
        // leaving the contract's ETH balance lower than pot.
        assertTrue(c.pot() == address(c).balance - initialNonPlayerBalance);
    }
}
